#!/usr/bin/env python3

import argparse
import csv
from collections import defaultdict
from pathlib import Path

import pysam


def parse_args():
    parser = argparse.ArgumentParser(
        description=(
            "Compare one or more paired-end BAM files against the truth TSV "
            "generated by readSimulator_truth_1M.py. Metrics are reported "
            "separately for ALL reads, truth-defined JUNCTION reads, and "
            "NON_JUNCTION reads."
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""\
Examples
--------
Evaluate one aligner:

  python3 compare_aligners.py \\
      --truth simulation/reference_truth.tsv \\
      --bam BOTAS botas.sorted.bam \\
      --tolerance 10 \\
      --tsv botas_metrics.tsv

Compare several aligners in one command:

  python3 compare_aligners.py \\
      --truth simulation/reference_truth.tsv \\
      --bam BOTAS botas.sorted.bam \\
      --bam Bowtie2 bowtie2.sorted.bam \\
      --bam BWA-MEM2 bwa_mem2.sorted.bam \\
      --bam minimap2 minimap2.sorted.bam \\
      --tolerance 10 \\
      --tsv alignment_comparison.tsv

Correctness rule
----------------
A mapped mate is counted as correct only when the reference sequence matches
truth, the strand matches truth, and the reported 1-based alignment start is
within --tolerance bp of truth.

The script reports read-level precision, recall and F1 for ALL, JUNCTION and
NON_JUNCTION. The JUNCTION category comes from simulator truth, not from the
aligner's XC tag. XC:Z:JUNCTION counts are reported separately when present.

Each --bam argument takes exactly two values: a display LABEL and BAM PATH.
Repeat --bam for multiple aligners.
"""
    )

    parser.add_argument(
        "--truth",
        required=True,
        help="Truth TSV produced by readSimulator_truth_1M.py",
    )
    parser.add_argument(
        "--bam",
        action="append",
        nargs=2,
        metavar=("LABEL", "PATH"),
        required=True,
        help=(
            "Aligner label and BAM path. Repeat for multiple aligners, e.g. "
            "--bam BOTAS botas.bam --bam Bowtie2 bowtie2.bam"
        ),
    )
    parser.add_argument(
        "--tolerance",
        type=int,
        default=10,
        help="Maximum allowed absolute start-position error in bp (default: 10)",
    )
    parser.add_argument(
        "--tsv",
        default=None,
        help="Optional output TSV containing one row per aligner and category",
    )

    return parser.parse_args()


def load_truth(path):
    truth = {}

    with open(path, newline="") as fh:
        reader = csv.DictReader(fh, delimiter="\t")

        required = {
            "pair_id",
            "ref1",
            "start1_1",
            "strand1",
            "read1_crosses_origin",
            "ref2",
            "start1_2",
            "strand2",
            "read2_crosses_origin",
            "reference_length",
        }

        missing = required - set(reader.fieldnames or [])
        if missing:
            raise ValueError(
                "Truth file is missing required columns: "
                + ", ".join(sorted(missing))
            )

        for row in reader:
            pair = row["pair_id"]
            L = int(row["reference_length"])

            truth[(pair, 1)] = {
                "ref": row["ref1"],
                "pos": int(row["start1_1"]),
                "strand": row["strand1"],
                "junction": row["read1_crosses_origin"] == "1",
                "L": L,
            }

            truth[(pair, 2)] = {
                "ref": row["ref2"],
                "pos": int(row["start1_2"]),
                "strand": row["strand2"],
                "junction": row["read2_crosses_origin"] == "1",
                "L": L,
            }

    if not truth:
        raise RuntimeError(f"No truth records found in {path}")

    return truth


def evaluate(bam_path, truth, tolerance):
    observed = {}

    with pysam.AlignmentFile(str(bam_path), "rb") as bam:
        for read in bam.fetch(until_eof=True):
            if read.is_secondary or read.is_supplementary:
                continue

            if read.is_read1:
                mate = 1
            elif read.is_read2:
                mate = 2
            else:
                continue

            key = (read.query_name, mate)

            # Preserve the first primary alignment for each mate.
            if key not in observed:
                observed[key] = read

    results = {
        "all": defaultdict(int),
        "junction": defaultdict(int),
        "non_junction": defaultdict(int),
    }

    junction_tags = 0

    for key, t in truth.items():
        category = "junction" if t["junction"] else "non_junction"
        read = observed.get(key)

        if read is None or read.is_unmapped:
            results["all"]["unmapped"] += 1
            results[category]["unmapped"] += 1
            continue

        if read.has_tag("XC") and read.get_tag("XC") == "JUNCTION":
            junction_tags += 1

        observed_pos = read.reference_start + 1
        observed_strand = "-" if read.is_reverse else "+"
        distance = abs(observed_pos - t["pos"])

        correct = (
            read.reference_name == t["ref"]
            and distance <= tolerance
            and observed_strand == t["strand"]
        )

        label = "correct" if correct else "wrong"
        results["all"][label] += 1
        results[category][label] += 1

    return results, junction_tags


def metrics(d):
    correct = d["correct"]
    wrong = d["wrong"]
    unmapped = d["unmapped"]
    total = correct + wrong + unmapped

    precision = correct / (correct + wrong) if correct + wrong else 0.0
    recall = correct / total if total else 0.0
    f1 = (
        2 * precision * recall / (precision + recall)
        if precision + recall
        else 0.0
    )

    return {
        "total": total,
        "correct": correct,
        "wrong": wrong,
        "unmapped": unmapped,
        "precision": precision,
        "recall": recall,
        "f1": f1,
    }


def print_report(label, results, junction_tags):
    print()
    print("=" * 70)
    print(label)
    print("=" * 70)

    summary = {}

    for category in ["all", "junction", "non_junction"]:
        m = metrics(results[category])
        summary[category] = m

        print(f"\n{category.upper()}")
        print(f"Total:      {m['total']}")
        print(f"Correct:    {m['correct']}")
        print(f"Wrong:      {m['wrong']}")
        print(f"Unmapped:   {m['unmapped']}")
        print(f"Precision:  {m['precision']:.6f}")
        print(f"Recall:     {m['recall']:.6f}")
        print(f"F1:         {m['f1']:.6f}")

    print(f"\nXC:Z:JUNCTION tags: {junction_tags}")
    return summary


def write_tsv(path, rows):
    fields = [
        "aligner",
        "category",
        "total",
        "correct",
        "wrong",
        "unmapped",
        "precision",
        "recall",
        "f1",
        "junction_tags",
    ]

    out = Path(path)
    out.parent.mkdir(parents=True, exist_ok=True)

    with open(out, "w", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=fields, delimiter="\t")
        writer.writeheader()
        writer.writerows(rows)


def main():
    args = parse_args()

    if args.tolerance < 0:
        raise ValueError("--tolerance must be >= 0")

    truth_path = Path(args.truth)
    if not truth_path.is_file():
        raise FileNotFoundError(f"Truth file not found: {truth_path}")

    truth = load_truth(truth_path)
    tsv_rows = []

    for label, bam_path_string in args.bam:
        bam_path = Path(bam_path_string)
        if not bam_path.is_file():
            raise FileNotFoundError(f"BAM file not found for {label}: {bam_path}")

        results, junction_tags = evaluate(
            bam_path=bam_path,
            truth=truth,
            tolerance=args.tolerance,
        )

        summary = print_report(label, results, junction_tags)

        for category, m in summary.items():
            tsv_rows.append(
                {
                    "aligner": label,
                    "category": category,
                    "total": m["total"],
                    "correct": m["correct"],
                    "wrong": m["wrong"],
                    "unmapped": m["unmapped"],
                    "precision": f"{m['precision']:.6f}",
                    "recall": f"{m['recall']:.6f}",
                    "f1": f"{m['f1']:.6f}",
                    "junction_tags": junction_tags,
                }
            )

    if args.tsv:
        write_tsv(args.tsv, tsv_rows)
        print(f"\nWrote summary TSV: {args.tsv}")


if __name__ == "__main__":
    main()
